PREFIX mvp: <https://w3id.org/mommis/mvp/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?glycan ?label ?glytoucan ?assertion ?status WHERE {
 ?glycan mvp:glytoucan ?glytoucan; rdfs:label ?label.
 ?assertion mvp:glycan ?glycan; mvp:stageKey "utilization"; mvp:reviewStatus ?status.
} ORDER BY ?assertion

PREFIX mvp: <https://w3id.org/mommis/mvp/>
SELECT ?assertion ?statement ?system ?exposure ?comparator ?status WHERE {
 ?assertion mvp:stageKey ?stage; mvp:statement ?statement; mvp:system ?system;
 mvp:exposure ?exposure; mvp:comparator ?comparator; mvp:reviewStatus ?status.
 FILTER (?stage IN ("immune", "epithelial"))
} ORDER BY ?assertion

PREFIX mvp: <https://w3id.org/mommis/mvp/>
SELECT ?assertion ?document ?source ?location ?origin ?status WHERE {
 ?assertion a mvp:EvidenceAssertion; mvp:source ?source; mvp:sourceLocation ?location;
 mvp:origin ?origin; mvp:reviewStatus ?status.
 OPTIONAL { ?assertion mvp:original_sources ?filename. }
 BIND(COALESCE(?filename, STR(?source)) AS ?document)
} ORDER BY ?assertion

PREFIX mvp: <https://w3id.org/mommis/mvp/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?entity ?label ?candidateMapping WHERE {
 ?entity rdfs:label ?label; mvp:candidateMapping ?candidateMapping.
} ORDER BY ?entity
